+
         await tester.pumpWidget(_wrap(fakeVaultRepository));
         await tester.pumpAndSettle();

         expect(find.text('Digite seu PIN'), findsOneWidget);
+        expect(
+          find.text('Não foi possível reconhecer — digite seu PIN'),
